from zoneinfo import ZoneInfo
def format_epoch(epoch,zone):
    if type(epoch) is not int:raise ValueError('integer UTC epoch required')
    if not isinstance(zone,str) or not zone:raise ValueError('IANA zone required')
    value=datetime.fromtimestamp(epoch,timezone.utc).astimezone(ZoneInfo(zone))
    return {'iso':value.isoformat(timespec='seconds'),'fold':value.fold}
```

