import os
from pathlib import Path
def read_statm(pid,proc_root='/proc'):
    if type(pid) is not int or pid<=0:raise ValueError('positive integer PID required')
    page_size=os.sysconf('SC_PAGE_SIZE')
    if type(page_size) is not int or page_size<=0:raise RuntimeError('invalid native page size')
    fields=(Path(proc_root)/str(pid)/'statm').read_text(encoding='ascii').split()
    if len(fields)!=7 or any(not x.isascii() or not x.isdecimal() for x in fields):
        raise ValueError('malformed statm')
    values=[int(x) for x in fields]
    return {'pid':pid,'page_size':page_size,'size_bytes':values[0]*page_size,
            'resident_bytes':values[1]*page_size,'shared_bytes':values[2]*page_size}
```

原题知识说明：
基础页大小依体系结构与内核配置而异，应从目标系统的getconf PAGE_SIZE或sysconf获取，并确认字段确实以页为单位。HugeTLB页又是独立概念，不能拿其大小换算普通页字段；记录单位和采样主机，避免跨架构容量误报。

